// lock -- protects a critical section, single-threaded access guaranteed
private readonly object _lockObj = new object();  // dedicated, private lock object
private int _counter;

public void Increment()
{
    lock (_lockObj)
    {
        _counter++;   // safe -- only one thread executes this at a time
    }
}

// Interlocked -- cheaper than lock for simple atomic operations
private int _atomicCounter;
public void IncrementFast() => Interlocked.Increment(ref _atomicCounter);

// SemaphoreSlim -- the async-compatible alternative to lock
private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);

public async Task DoWorkAsync()
{
    await _semaphore.WaitAsync();
    try
    {
        await SomeAsyncOperation();   // ✓ can await while "locked" -- lock statement cannot do this
    }
    finally
    {
        _semaphore.Release();         // always release, even on exception
    }
}

